import React, { useState } from "react";
import "./Questionnaire.css";

function Questionnaire({ onNext, updateData }) {
  const [answers, setAnswers] = useState({
    incomeRange: "",
    spendingRange: "",
    savingRange: ""
  });

  const handleChange = (e) => {
    setAnswers({ ...answers, [e.target.name]: e.target.value });
  };

  const handleContinue = () => {
    updateData({ questionnaire: answers });
    onNext();
  };

  return (
    <div className="questionnaire-container">
      <div className="questionnaire-card">
        <h2 className="questionnaire-title">Financial Questionnaire</h2>

        {/* Income Range */}
        <div className="form-group">
          <label className="form-label">Monthly Income Range</label>
          <select
            name="incomeRange"
            className="form-select"
            onChange={handleChange}
          >
            <option value="">Select</option>
            <option>Below 10,000</option>
            <option>10,000 – 25,000</option>
            <option>25,000 – 50,000</option>
            <option>50,000 – 1,00,000</option>
            <option>Above 1,00,000</option>
          </select>
        </div>

        {/* Spending Range */}
        <div className="form-group">
          <label className="form-label">Monthly Spending Range</label>
          <select
            name="spendingRange"
            className="form-select"
            onChange={handleChange}
          >
            <option value="">Select</option>
            <option>Below 5,000</option>
            <option>5,000 – 15,000</option>
            <option>15,000 – 30,000</option>
            <option>30,000 – 60,000</option>
            <option>Above 60,000</option>
          </select>
        </div>

        {/* Saving Range */}
        <div className="form-group">
          <label className="form-label">Monthly Saving Range</label>
          <select
            name="savingRange"
            className="form-select"
            onChange={handleChange}
          >
            <option value="">Select</option>
            <option>Below 2,000</option>
            <option>2,000 – 10,000</option>
            <option>10,000 – 25,000</option>
            <option>25,000 – 50,000</option>
            <option>Above 50,000</option>
          </select>
        </div>

        <button className="next-button" onClick={handleContinue}>
          Continue
        </button>
      </div>
    </div>
  );
}

export default Questionnaire;
